content:
Review this change for security vulnerabilities.

Changed files (you may Read these and any other file in the repo):
  - src/js/phase1/actions_extra.js
  - src/js/ui/modal.js

Unified diff (only + lines are new):

=== DIFF: src/js/phase1/actions_extra.js ===
@@ -12,36 +12,13 @@ function addStreetExtras(state, actions) {
   // === 街头生存类（任何街头地点都行） ===
   actions.push({
     id: "scavenge_trash",
-    name: "🗑️ 翻垃圾桶找废品",
